fn bdf_exp(x: f64) -> f64 with Mut, Div {
    if x>700.0{return 1.0e200} if x<0.0-700.0{return 0.0}
    var kf=x/0.6931471805599453;var k:i64=0
    if kf>=0.0{k=kf as i64}else{k=(kf as i64)-1}
