}
fn bdf_rhs(rhs_id: i64, y: &[f64; 64], n: i64, out: &![f64; 64]) with Mut {
    var k:i64=0
    if rhs_id==0{out[0]=0.0-1000.0*y[0];out[1]=0.0-1.0*y[1];k=2;while k<n{out[k]=0.0;k=k+1}return}
