// Smoke test for stdlib/darwin_pbpk/tsit5_pbpk28.sio + core/pbpk28_params.sio
// (Stage G-ε-15).
//
// Runs the fully-coupled CN step on the rapamycin profile from a 0.05 mg
// IV bolus (= 0.01 mg/L blood C_v at t=0) for 30 h with dt = 0.1 h
// (300 steps, rel_mid = 0). Confirms:
//
//   1. Step is stable — no NaN / inf / negative concentrations.
//   2. Total mass strictly decays (the central CL drains the system,
//      no source).
//   3. Liver organ-average concentration tracks blood concentration with the
//      expected Kp=5.4 accumulation (peak C_liver,avg > 3× C_blood).
//   4. Brain organ-average stays low (Kp=0.10 + small PS → BBB barrier
//      keeps C_brain,avg < 0.2× C_blood).
//
// Math parity with the parity ref is enforced by case 1 of
// `dissertation_pbpk28_parity_gate.sh` once the parity ref is rewired to
// import this module (G-ζ-1).

use darwin_pbpk::core::pbpk28_params::*
use darwin_pbpk::tsit5_pbpk28::*

fn fmt_6(x: f64) -> i64 { return (x * 1000000.0) as i64 }

fn main() with Mut, Div, IO {
    let p = pbpk28_params_rapamycin()
    var s = pbpk28_state_zero()
    s.cv[0] = 0.01      // 0.05 mg / 5 L = 0.01 mg/L blood C_v at t=0

    let dt = 0.001     // matches parity ref's dt
    let n_steps = 30000   // 30 h

    let m_initial = pbpk28_total_mass(s, p)
    print("initial total mass (mg)*1e6=")
    println(fmt_6(m_initial))

    var step = 0
    var m_prev = m_initial
    var liver_peak = 0.0
    var brain_peak = 0.0
    while step < n_steps {
        s = pbpk28_full_cn_step(s, p, 0.0, dt)
        let m_now = pbpk28_total_mass(s, p)

        // Invariant 1: no NaN / inf / negative.
        let inv_ok = (s.cv[0] >= 0.0) && (s.cv[0] < 1.0e3)
        if !inv_ok {
            println("FAIL: blood C_v out of physical range")
            return
        }

        // Invariant 2: total mass decays.
        if m_now > m_prev * 1.0001 {
            print("FAIL: total mass grew at step="); print(step + 1)
            print(" m_prev*1e6="); print(fmt_6(m_prev))
            print(" m_now*1e6="); println(fmt_6(m_now))
            return
        }
        m_prev = m_now

        // Track peaks for liver / brain organ-averages.
        let cavg_liver = pbpk28_organ_average(s, p, 1)
        let cavg_brain = pbpk28_organ_average(s, p, 3)
        if cavg_liver > liver_peak { liver_peak = cavg_liver }
        if cavg_brain > brain_peak { brain_peak = cavg_brain }

        let report = (step + 1) == 100 || (step + 1) == 6000 || (step + 1) == 30000
        if report {
            print("step="); print(step + 1)
            print(" cb*1e6=");         print(fmt_6(s.cv[0]))
            print(" cliver_avg*1e6="); print(fmt_6(cavg_liver))
            print(" cbrain_avg*1e6="); println(fmt_6(cavg_brain))
        }
        step = step + 1
    }

    let m_final = pbpk28_total_mass(s, p)
    print("final total mass (mg)*1e6=")
    println(fmt_6(m_final))

    // Mass decayed monotonically and is essentially gone: with CL_hep=12.4
    // L/h on V_eff = V_b + Σ V_i·Kp_i ≈ 49 L, exp(-12.4·30/49) ≈ 5e-4 so
    // we expect m_final/m_initial ≈ 5e-4. Allow [1e-5, 0.1].
    let decay_ratio = m_final / m_initial
    let decay_ok = (decay_ratio > 1.0e-5) && (decay_ratio < 0.1)
    if !decay_ok {
        print("FAIL: mass decay outside band [1e-5, 0.1]: ratio*1e6=")
        println(fmt_6(decay_ratio))
        return
    }

    // Liver peak (Kp=5.4 + early high blood) > 3× initial blood. C_blood at
    // t=0 is 0.01 mg/L; liver organ-average reaches at least 0.005 mg/L.
    let liver_ok = liver_peak > 5.0e-3
    if !liver_ok {
        print("FAIL: liver peak too low: ")
        println(fmt_6(liver_peak))
        return
    }

    // Brain (Kp=0.10, PS=88) stays below 0.2× initial blood = 2e-3 mg/L.
    let brain_ok = brain_peak < 2.0e-3
    if !brain_ok {
        print("FAIL: brain peak too high (BBB leak?): ")
        println(fmt_6(brain_peak))
        return
    }

    println("PBPK28_CORE_SMOKE_PASS")
}

//@ run-pass
//@ expect-stdout-contains: VENLAFAXINE_XR_LARGE_DT_PASS
//
// Steady-state readout at step sizes where the absorption exponential needs
// range reduction (ka·dt > 0.5, i.e. dt > 0.79 h): dt = 1 h (one halving)
// and dt = 24 h (five halvings, x = −15.12). Before the reduction, the
// 19-term Taylor series returned −9.2e4 at dt = 24 h, and the gut released
// millions of mg per step.
//
//   1. Physical bound. At steady state everything the parent eliminates
//      through CL_c in one interval came from that interval's absorbed dose,
//      at most the 75 mg released, so CL_c·AUC_parent ≤ 75 mg; likewise
//      CL_odv·AUC_odv ≤ 75 mg. Both are checked against the UPPER end of each
//      AUC's certified interval (AUC + err): the whole interval, and so the
//      exact steady state, must respect the dose bound.
//   2. The closed-form steady state lies inside the run's certified interval.
//      At these dt the CN steps clamp heavily, so the interval is wide
//      (dt = 24: ±1.5 %), but it is derived, not chosen.

use darwin_pbpk::scenarios::venlafaxine_xr::*
use darwin_pbpk::release::matrix_er::*
use darwin_pbpk::drugs::venlafaxine::*

fn ldt_ok(pheno: i32, dt: f64) -> bool with IO, Mut, Div, Panic {
    let iv = vfx_ss_interval(pheno, venlafaxine_xr_matrix_gohel2008(), 10, 24.0, dt)
    let dose = 75.0
    let cf = vfx_ss_ratio_closed_form(pheno)
    let elim_p = venlafaxine_cl_parent_central_pgx(pheno) * (iv.auc_parent + iv.err_auc_parent)
    let elim_o = venlafaxine_cl_odv_pgx(pheno) * (iv.auc_odv + iv.err_auc_odv)
    println("pheno, dt, ratio, closed form, lo, CL_c*AUC_p upper (mg), CL_odv*AUC_o upper (mg):")
    println(pheno)
    println(dt)
    println(vfx_ss_ratio(iv))
    println(cf)
    println(vfx_ss_ratio_lo(iv))
    println(elim_p)
    println(elim_o)
    if !(elim_p <= dose && elim_o <= dose) {
        println("FAIL: steady-state elimination exceeds the dose per interval")
        return false
    }
    if !(vfx_ss_ratio_lo(iv) <= cf && cf <= vfx_ss_ratio_hi(iv)) {
        println("FAIL: closed form outside certified interval")
        return false
    }
    return true
}

fn main() with Mut, Div, IO, Panic {
    var ph: i32 = 0
    while ph < 4 {
        if !ldt_ok(ph, 1.0) { return }
        if !ldt_ok(ph, 24.0) { return }
        ph = ph + 1
    }
    println("VENLAFAXINE_XR_LARGE_DT_PASS")
}

//@ run-pass
// tests/run-pass/display_headless.sio — Headless canvas smoke test
//
// Exercises stdlib/display/canvas + stdlib/display/font without opening
// a window, writing pixels to a heap buffer and verifying values.
//
// Expected output:
//   DISPLAY_HEADLESS_PASS
//   exit 0

use display::canvas::{Canvas, canvas_clear, canvas_set_pixel, canvas_fill_rect,
                       canvas_draw_line, canvas_draw_circle, canvas_fill_circle,
                       canvas_draw_char, canvas_draw_text}
use display::font::{font_glyph, font_draw_char}

fn make_headless_canvas(w: i64, h: i64) -> Canvas with Alloc {
    let pix = heap_alloc(w * h * 8) as *mut i64
    Canvas { pixels: pix, width: w, height: h }
}

fn read_pixel(c: &Canvas, x: i64, y: i64) -> i64 {
    read_i64(c.pixels, y * c.width + x)
}

fn main() with IO, Alloc, Mut, Div {
    let w: i64 = 128
    let h: i64 = 128
    var c = make_headless_canvas(w, h)

    // 1. canvas_clear
    canvas_clear(&!c, 10, 20, 30)
    let p0 = read_pixel(&c, 0, 0)
    let expected_clear = 30 | (20 << 8) | (10 << 16)
    assert(p0 == expected_clear)

    // 2. canvas_set_pixel
    canvas_set_pixel(&!c, 64, 64, 255, 0, 0)
    let p1 = read_pixel(&c, 64, 64)
    let expected_red = 0 | (0 << 8) | (255 << 16)
    assert(p1 == expected_red)

    // 3. canvas_fill_rect — paint a 10×10 blue square at (5,5)
    canvas_fill_rect(&!c, 5, 5, 10, 10, 0, 0, 255)
    let corner = read_pixel(&c, 5, 5)
    let expected_blue = 255 | (0 << 8) | (0 << 16)
    assert(corner == expected_blue)
    // Pixel just outside rect should still be clear background
    let outside = read_pixel(&c, 15, 15)
    assert(outside == expected_clear)

    // 4. canvas_draw_line — draws at least one pixel along y=0 row
    canvas_clear(&!c, 0, 0, 0)
    canvas_draw_line(&!c, 0, 50, 127, 50, 200, 150, 100)
    let line_px = read_pixel(&c, 64, 50)
    let expected_line = 100 | (150 << 8) | (200 << 16)
    assert(line_px == expected_line)

    // 5. canvas_draw_circle — centre pixel won't be filled; check a nearby spoke
    canvas_clear(&!c, 0, 0, 0)
    canvas_draw_circle(&!c, 64, 64, 20, 0, 255, 0)
    // The top-most point of the circle should be colored
    let top = read_pixel(&c, 64, 44)
    let expected_green = 0 | (255 << 8) | (0 << 16)
    assert(top == expected_green)

    // 6. canvas_fill_circle — centre pixel and nearby are filled
    canvas_clear(&!c, 0, 0, 0)
    canvas_fill_circle(&!c, 64, 64, 10, 255, 128, 0)
    // Centre pixel must be filled
    let circ_center = read_pixel(&c, 64, 64)
    let expected_orange = 0 | (128 << 8) | (255 << 16)
    assert(circ_center == expected_orange)
    // Pixel well outside the radius must be unfilled
    let circ_outside = read_pixel(&c, 0, 0)
    assert(circ_outside == 0)

    // 7. font_glyph non-zero for printable char
    let g_a = font_glyph(65)  // 'A'
    assert(g_a != 0)
    let g_space = font_glyph(32)  // ' '
    assert(g_space == 0)

    // 8. font_draw_char writes some pixels
    canvas_clear(&!c, 0, 0, 0)
    font_draw_char(c.pixels, w, h, 65, 0, 0, 255, 255, 255)  // 'A'
    // At least the top row of 'A' glyph (bits 7-0 = row 0) should have pixels
    // Row 0 of 'A' glyph = 0x1C (from packed i64); check pixel at (2,0) which is bit 5
    let glyph_a = font_glyph(65)
    let row0 = glyph_a & 0xFF
    // Rather than hard-code bit positions, just check that at least one pixel in
    // the 8×8 box is white:
    var found_white = false
    var gy: i64 = 0
    while gy < 8 {
        var gx: i64 = 0
        while gx < 8 {
            let px = read_pixel(&c, gx, gy)
            if px != 0 {
                found_white = true
            }
            gx = gx + 1
        }
        gy = gy + 1
    }
    assert(found_white)

    heap_free(c.pixels as *mut i8)
    println("DISPLAY_HEADLESS_PASS")
}

