            println("")
            print("PARITY|pd_n=")
            println(state.n[i])
            println("")
        }
        i = i + 1
    }
}

fn main() -> i32 with IO, Mut, Div, Panic {
    println("DISSERTATION_PBPK28_PARITY_ALT v1")
