fn main() -> i32 with IO, Mut, Div, Panic {
    var passed: i32 = 0
    var failed: i32 = 0

    // T1: for loop basic range (already works)
    var sum: i64 = 0
    for i in 0..5 { sum = sum + i }
    if sum == 10 { passed = passed + 1 } else { println("T1 FAIL"); failed = failed + 1 }

