    var wl_none: Option<i64> = None
    var wl_hit: i64 = 0
    while let Some(x) = wl_none { wl_hit = wl_hit + 1 }
    if wl_hit == 0 { passed = passed + 1 } else { println("T4 FAIL"); failed = failed + 1 }

